-- Starter quiz question bank. Correct answers stay behind the RPC functions in migration 001.
on conflict (id) do update set published=excluded.published;

on conflict (id) do update set question_text=excluded.question_text,question_type=excluded.question_type,options=excluded.options,correct_option=excluded.correct_option,explanation=excluded.explanation,position=excluded.position,published=excluded.published;
